#!/usr/bin/env python3
"""Optimised analyser: single OCR pass per page at moderate scale."""
from __future__ import annotations

import io
import json
import re
import subprocess
import sys
from collections import defaultdict
from pathlib import Path

import fitz


DSE_ROOT = Path("/Users/sinchunyeung/Documents-local/Materials/Phy/DSE")
SOURCE_DIR = DSE_ROOT / "Year" / "MC"
OUT_DIR = Path("/tmp/dse_analysis")
OUT_DIR.mkdir(parents=True, exist_ok=True)

PAPERS = ["2015p1a", "2016p1a", "2017p1a", "2019p1a", "2020p1a"]
OCR_SCALE = 3.0  # single scale for both classification and label finding


def _tesseract(img_bytes: bytes, args: list[str]) -> str:
    result = subprocess.run(
        ["tesseract", "stdin", "stdout"] + args,
        input=img_bytes,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        check=True,
    )
    return result.stdout.decode("utf-8", errors="ignore")


def _img_bytes(page: fitz.Page, scale: float) -> bytes:
    pix = page.get_pixmap(matrix=fitz.Matrix(scale, scale), alpha=False)
    return pix.tobytes("png")


def ocr_text(page: fitz.Page, scale: float = OCR_SCALE, psm: str = "6") -> str:
    return _tesseract(_img_bytes(page, scale), ["--psm", psm])


def ocr_words(page: fitz.Page, scale: float = OCR_SCALE, psm: str = "11") -> list[dict]:
    text = _tesseract(_img_bytes(page, scale), ["--psm", psm, "tsv"])
    rows = text.splitlines()
    if not rows:
        return []
    header = rows[0].split("\t")
    out = []
    for r in rows[1:]:
        cells = r.split("\t")
        if len(cells) < len(header):
            continue
        out.append(dict(zip(header, cells)))
    return out


def classify(text: str) -> str:
    t = text.lower()
    if len(t.strip()) < 30:
        return "blank"
    if "formula sheet" in t or "data sheet" in t or "physical constants" in t:
        return "formula_sheet"
    if "instructions to candidates" in t:
        return "instructions"
    if "multiple choice questions" in t or "multiple-choice" in t:
        return "instructions"
    if "section a" in t and "answer all" in t:
        return "instructions"
    return "content"


QUESTION_RE = re.compile(r"^\*?(\d{1,2})[\.\)]?$")


def detect_labels_on_page(
    page: fitz.Page, scale: float, max_q: int, page_w: float, page_h: float
) -> list[tuple[int, float, float, float]]:
    """Return [(n, x, y, conf)] in PDF point coordinates.

    Heuristics:
      - x must be in the left margin band (page left ~35pt to ~120pt)
      - y must be inside body (35 to page_h - 35)
      - text must be a 1- or 2-digit number
      - confidence threshold to drop obvious noise
    """
    found: list[tuple[int, float, float, float]] = []
    for psm in ("11", "6"):
        for row in ocr_words(page, scale=scale, psm=psm):
            text = (row.get("text") or "").strip()
            if not text:
                continue
            try:
                x = float(row["left"]) / scale
                y = float(row["top"]) / scale
                conf = float(row.get("conf", -1))
            except (KeyError, ValueError):
                continue
            if not (35 <= x <= 120):
                continue
            if not (35 <= y <= page_h - 35):
                continue
            m = QUESTION_RE.match(text)
            if not m:
                continue
            n = int(m.group(1))
            if not (1 <= n <= max_q):
                continue
            # accept moderate confidence only
            if conf < 25 and psm == "11":
                continue
            found.append((n, x, y, conf))
    # Deduplicate
    deduped: list[tuple[int, float, float, float]] = []
    for item in sorted(found, key=lambda r: -r[3]):
        n, x, y, conf = item
        if any(
            n == m[0] and abs(x - m[1]) < 6 and abs(y - m[2]) < 10
            for m in deduped
        ):
            continue
        deduped.append(item)
    return deduped


def analyse(paper: str) -> dict:
    doc = fitz.open(SOURCE_DIR / f"{paper}.pdf")
    n_pages = len(doc)
    page_h = doc[0].rect.height
    page_w = doc[0].rect.width

    page_info: list[dict] = []
    labels_per_page: dict[int, list[tuple[int, float, float]]] = {}
    by_number: dict[int, list[tuple[int, float, float]]] = defaultdict(list)

    # Pass 1: classify all pages, OCR text only at low cost
    for i in range(n_pages):
        text = ocr_text(doc[i], scale=OCR_SCALE, psm="6")
        kind = classify(text)
        page_info.append({"index": i, "kind": kind, "text_len": len(text.strip())})

    # Pass 2: find labels on content pages (skip covers/blank/formula/instructions)
    max_q = 45  # ceiling
    for info in page_info:
        i = info["index"]
        if info["kind"] != "content":
            continue
        raw = detect_labels_on_page(doc[i], OCR_SCALE, max_q, page_w, page_h)
        labels_per_page[i] = [(n, x, y) for n, x, y, _c in raw]
        for n, x, y in labels_per_page[i]:
            by_number[n].append((i, x, y))

    # Decide question count: highest number with a label on a non-formula page
    expected_n = max(by_number.keys()) if by_number else 0

    # Choose canonical location per number
    # Heuristic: pick the candidate from the page with the densest label set,
    # and the leftmost/uppermost within that page.
    page_density = {
        p: sum(1 for _n, _x, _y in items)
        for p, items in labels_per_page.items()
    }
    chosen: dict[int, tuple[int, float, float]] = {}
    for n in range(1, expected_n + 1):
        cands = by_number.get(n, [])
        if not cands:
            continue
        cands_sorted = sorted(
            cands,
            key=lambda c: (-page_density.get(c[0], 0), c[1], c[2]),
        )
        chosen[n] = cands_sorted[0]

    final_mapping: dict[str, list] = {}
    for n in sorted(chosen.keys()):
        page_index, x, y = chosen[n]
        # Re-confirm: find the closest OCR match for n on that page
        raw = detect_labels_on_page(doc[page_index], OCR_SCALE, expected_n, page_w, page_h)
        reps = [r for r in raw if r[0] == n]
        if reps:
            reps.sort(key=lambda r: abs(r[1] - x) + abs(r[2] - y))
            _n, x2, y2, _c = reps[0]
            x, y = x2, y2
        final_mapping[str(n)] = [int(page_index), round(float(x), 2), round(float(y), 2)]

    exclude = [info["index"] for info in page_info if info["kind"] != "content"]
    content_zero = [
        info["index"]
        for info in page_info
        if info["kind"] == "content" and not labels_per_page.get(info["index"])
    ]

    doc.close()

    return {
        "paper": paper,
        "page_count": n_pages,
        "page_dimensions": [page_w, page_h],
        "page_classification": page_info,
        "labels_per_page": {str(k): v for k, v in labels_per_page.items()},
        "candidates_per_number": {str(k): v for k, v in by_number.items()},
        "expected_question_number_max": expected_n,
        "mapping": final_mapping,
        "question_count": len(final_mapping),
        "exclude_pages": exclude,
        "exclude_reason": {str(i): page_info[i]["kind"] for i in exclude},
        "content_pages_with_no_labels": content_zero,
    }


def main() -> None:
    summary: dict[str, dict] = {}
    for paper in PAPERS:
        print(f"=== {paper} ===", flush=True)
        result = analyse(paper)
        (OUT_DIR / f"{paper}_analysis.json").write_text(json.dumps(result, indent=2, default=str))
        summary[paper] = {
            "page_count": result["page_count"],
            "question_count": result["question_count"],
            "exclude_pages": result["exclude_pages"],
            "exclude_reasons": result["exclude_reason"],
        }
        print(
            f"  pages={result['page_count']}  "
            f"questions_found={result['question_count']}  "
            f"excluded={result['exclude_pages']}",
            flush=True,
        )
        for k, v in list(result["mapping"].items())[:8]:
            print(f"    {k} -> p{v[0]+1} x={v[1]} y={v[2]}", flush=True)
    (OUT_DIR / "summary.json").write_text(json.dumps(summary, indent=2))
    print("DONE", flush=True)


if __name__ == "__main__":
    main()

